-- NwebOS Verwaltung seed (PR B follows): copies today's live texts into the 0019 tables so the first admin edit
-- does not replace the code fallback. Texts come from src/nwebos.js (about(), PROJ) and src/nwebos-apps.js (SITE_LOG).
-- Idempotent: site_blocks uses INSERT OR IGNORE, projects/changelog only fill an EMPTY table. Additive; no data dropped.
-- Applied by CF Deployer right after 0019, before the Verwaltung UI is used:
--   npx wrangler d1 execute nwebnotfound-guestbook --remote --file migrations/0020_admin_seed.sql

-- site_blocks: 7 rows (no about.text)
INSERT OR IGNORE INTO site_blocks (key, lang, json, version, updated_at) VALUES ('home.hero', 'de', '{"eyebrow":"Nils'' Ecke im Internet","name":"Nils","lead":"Ich baue Dinge, die mir Spaß machen: Webseiten, einen Minecraft-Server für Freunde, Musik und Geschichten. Hier landet alles, sobald es fertig genug ist."}', 1, 1762560000000);
INSERT OR IGNORE INTO site_blocks (key, lang, json, version, updated_at) VALUES ('home.hero', 'en', '{"eyebrow":"Nils'' corner of the internet","name":"Nils","lead":"I build things I enjoy: websites, a Minecraft server for friends, music and stories. Everything lands here once it''s ready enough."}', 1, 1762560000000);
INSERT OR IGNORE INTO site_blocks (key, lang, json, version, updated_at) VALUES ('home.facts', 'de', '{"rows":[{"icon":"site","k":"Baut","v":"diese Seite und einen MC-Server"},{"icon":"music","k":"Macht","v":"Musik in FL Studio"},{"icon":"text","k":"Schreibt","v":"einen Roman in Kapiteln"},{"icon":"heart","k":"Mag","v":"Pixel-Art, gemütliche Spiele, Sommer"}]}', 1, 1762560000000);
INSERT OR IGNORE INTO site_blocks (key, lang, json, version, updated_at) VALUES ('home.facts', 'en', '{"rows":[{"icon":"site","k":"Builds","v":"this site and an MC server"},{"icon":"music","k":"Makes","v":"music in FL Studio"},{"icon":"text","k":"Writes","v":"a novel in chapters"},{"icon":"heart","k":"Likes","v":"pixel art, cosy games, summer"}]}', 1, 1762560000000);
INSERT OR IGNORE INTO site_blocks (key, lang, json, version, updated_at) VALUES ('home.xp', '*', '{"value":0.64}', 1, 1762560000000);

-- projects: 6 rows in PROJ order. One statement with one guard (D1 caps compound SELECTs, and a per-row guard would stop after row 1).
INSERT INTO projects (sort, status, progress, href, icon, title_de, title_en, text_de, text_en, version, updated_at)
SELECT json_extract(value, '$.sort'), json_extract(value, '$.status'), json_extract(value, '$.progress'), json_extract(value, '$.href'), json_extract(value, '$.icon'), json_extract(value, '$.title_de'), json_extract(value, '$.title_en'), json_extract(value, '$.text_de'), json_extract(value, '$.text_en'), 1, 1762560000000
FROM json_each('[{"sort":1,"status":"live","progress":10,"href":"/about","icon":"about","title_de":"Diese Website","title_en":"This website","text_de":"Mein Zuhause im Netz. Gästebuch, Blog, zweisprachig, selbst gebaut auf Cloudflare Workers.","text_en":"My home on the web. Guestbook, blog, two languages, built by me on Cloudflare Workers."},{"sort":2,"status":"live","progress":10,"href":"https://mc.nwebnotfound.dev/","icon":"minecraft","title_de":"Minecraft-Server","title_en":"Minecraft server","text_de":"Kleiner Vanilla+-Server für Freunde mit eigener Economy, Markt und Wiki.","text_en":"A small Vanilla+ server for friends with its own economy, market and wiki."},{"sort":3,"status":"neu","progress":8,"href":"/blog","icon":"blog","title_de":"Blog","title_en":"Blog","text_de":"Was ich baue, was schiefging und was ich dabei gelernt habe.","text_en":"What I build, what went wrong and what I learned."},{"sort":4,"status":"bald","progress":3,"href":"/music","icon":"music","title_de":"Musik","title_en":"Music","text_de":"Loops, Beats und Stems aus FL Studio.","text_en":"Loops, beats and stems from FL Studio."},{"sort":5,"status":"bald","progress":3,"href":"/writing","icon":"writing","title_de":"Texte & Roman","title_en":"Writing & novel","text_de":"Eine Geschichte in Kapiteln.","text_en":"A story in chapters."},{"sort":6,"status":"idee","progress":1,"href":"/pixelwand","icon":"portfolio","title_de":"Pixelwand","title_en":"Pixel wall","text_de":"Eine gemeinsame Leinwand, auf der jeder ein paar Pixel setzt.","text_en":"A shared canvas where everyone sets a few pixels."}]')
WHERE NOT EXISTS (SELECT 1 FROM projects);

-- changelog: 6 rows, status live, sort = row index (1..6), same single-statement guard
INSERT INTO changelog (day, area, title_de, title_en, text_de, text_en, status, sort, version, updated_at)
SELECT json_extract(value, '$.day'), json_extract(value, '$.area'), json_extract(value, '$.title_de'), json_extract(value, '$.title_en'), json_extract(value, '$.text_de'), json_extract(value, '$.text_en'), 'live', json_extract(value, '$.sort'), 1, 1762560000000
FROM json_each('[{"day":"2026-11-07","area":"blog","title_de":"Blog mit Editor","title_en":"Blog with an editor","text_de":"Beiträge entstehen jetzt im Editor auf der Website, mit Vorschau, Autosave, Suche und RSS.","text_en":"Posts are now written in the editor on the website, with preview, autosave, search and RSS.","sort":1},{"day":"2026-11-07","area":"website","title_de":"Saubere Links pro Sprache","title_en":"Clean links per language","text_de":"Jeder Blog-Beitrag hat eine feste Adresse auf Deutsch und auf Englisch.","text_en":"Every blog post has a fixed address in German and in English.","sort":2},{"day":"2026-11-07","area":"website","title_de":"NwebOS-Desktop","title_en":"NwebOS desktop","text_de":"Die Hauptseite als kleines Betriebssystem: Fenster, Taskleiste, Startmenü.","text_en":"The main site as a tiny operating system: windows, taskbar, start menu.","sort":3},{"day":"2026-11-06","area":"website","title_de":"Neue Startseite","title_en":"New home page","text_de":"Die Hauptseite stellt Nils und seine Projekte vor.","text_en":"The main site introduces Nils and his projects.","sort":4},{"day":"2026-11-06","area":"website","title_de":"Schnellere Website","title_en":"Faster website","text_de":"Styles, Skripte und Bilder werden besser zwischengespeichert.","text_en":"Styles, scripts and images are cached better.","sort":5},{"day":"2026-11-06","area":"website","title_de":"Eine Navigation für alles","title_en":"One navigation for everything","text_de":"Hauptseite und Server-Seite teilen sich dieselbe Leiste.","text_en":"The main site and the server site share the same bar.","sort":6}]')
WHERE NOT EXISTS (SELECT 1 FROM changelog);
